from pathlib import Path
p=Path('caso001-rev01/index.html')
s=p.read_text()

css_anchor='@media(max-width:900px){.top{display:grid}'
css='''\n/* P2.12D.2 · PRÓLOGO CINEMATOGRÁFICO REV01 */\n.prologueShell{position:fixed;inset:0;z-index:9999;background:#050403;color:#f1e6d8;display:grid;place-items:center;overflow:hidden}.prologueShell.hidden{display:none!important}.prologueShell:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 30%,rgba(93,57,34,.25),transparent 36%),radial-gradient(circle at 14% 20%,rgba(143,35,31,.12),transparent 30%),linear-gradient(180deg,#090705 0,#030303 100%);animation:prologueBreath 8s ease-in-out infinite alternate}.prologueShell:after{content:"";position:absolute;inset:0;pointer-events:none;opacity:.32;background:repeating-linear-gradient(0deg,rgba(255,255,255,.022) 0 1px,transparent 1px 4px),linear-gradient(90deg,transparent 0 49.8%,rgba(201,169,116,.025) 50%,transparent 50.2%);background-size:auto,52px 52px}.prologueFrame{position:relative;z-index:2;width:min(1050px,calc(100vw - 28px));min-height:min(690px,calc(100vh - 28px));border:1px solid #4c3827;background:linear-gradient(160deg,rgba(15,12,10,.94),rgba(5,5,5,.96));box-shadow:0 28px 90px rgba(0,0,0,.65),inset 0 0 0 1px rgba(218,181,115,.035);display:grid;grid-template-rows:auto 1fr auto;overflow:hidden}.prologueTop{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding:18px 20px;border-bottom:1px solid #3d2e22}.prologueBrand{font-size:10px;letter-spacing:.24em;color:#b9a181;font-weight:950}.prologueTopActions{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.prologueMiniBtn{border:1px solid #5a432f;background:#12100e;color:#d9c4a6;border-radius:4px;padding:7px 9px;font-size:10px;letter-spacing:.08em;font-weight:900;cursor:pointer}.prologueMiniBtn:hover{border-color:#a67847}.prologueSceneWrap{position:relative;display:grid;place-items:center;padding:32px 42px 22px;min-height:470px}.prologueScene{width:min(820px,100%);display:grid;grid-template-columns:minmax(220px,.7fr) minmax(0,1.3fr);gap:46px;align-items:center;animation:sceneIn .48s ease-out both}.prologueVisual{height:310px;position:relative;display:grid;place-items:center}.prologueVisual:before{content:"";position:absolute;inset:16px;border:1px solid #3c2d21;box-shadow:inset 0 0 40px #000}.prologueVisual:after{content:"";position:absolute;width:200px;height:200px;border-radius:50%;background:radial-gradient(circle,rgba(146,38,34,.18),transparent 67%);filter:blur(3px)}.sceneGlyph{position:relative;z-index:2;font-family:Georgia,serif;font-size:92px;color:#caa468;text-shadow:0 10px 32px #000;opacity:.9}.sceneGlyph.small{font-size:58px}.sceneSix{position:relative;z-index:2;width:210px;height:210px}.sceneSix i{position:absolute;width:42px;height:42px;border-radius:50%;border:2px solid #b68d58;background:#17120e;box-shadow:0 8px 20px #0008}.sceneSix i:nth-child(1){left:84px;top:4px}.sceneSix i:nth-child(2){right:14px;top:51px}.sceneSix i:nth-child(3){right:14px;bottom:38px}.sceneSix i:nth-child(4){left:84px;bottom:2px}.sceneSix i:nth-child(5){left:14px;bottom:38px}.sceneSix i:nth-child(6){left:14px;top:51px}.sceneSix:after{content:"";position:absolute;inset:54px;border:1px solid #5a432e;border-radius:50%;box-shadow:0 0 0 18px rgba(86,55,35,.06)}.scenePaper{position:relative;z-index:2;width:156px;height:205px;background:linear-gradient(135deg,#d6bf99,#ad895f);box-shadow:14px 18px 0 #15100d,-10px -10px 0 #2a211a;transform:rotate(-4deg);border:1px solid #694c31}.scenePaper:before{content:"";position:absolute;left:22px;right:22px;top:45px;height:7px;background:#654b35;box-shadow:0 23px 0 #806247,0 46px 0 #806247,0 69px 0 #806247,0 92px 0 #806247}.scenePaper:after{content:"CONFIDENCIAL";position:absolute;left:18px;bottom:22px;border:3px solid rgba(117,31,28,.65);color:rgba(117,31,28,.72);font-weight:950;font-size:12px;letter-spacing:.1em;padding:5px;transform:rotate(-8deg)}.sceneQuotes{position:relative;z-index:2;width:220px;display:grid;gap:12px}.sceneQuotes span{display:block;border-left:3px solid #852823;background:#17130f;padding:11px 13px;color:#cdbba5;font-family:Georgia,serif;font-size:18px;transform:rotate(var(--r))}.sceneMissing{position:relative;z-index:2;width:175px;height:215px;border:2px dashed #8e6e49;display:grid;place-items:center;color:#9c7d58;font:900 74px/1 Georgia,serif;box-shadow:inset 0 0 45px rgba(0,0,0,.55)}.sceneNetwork{position:relative;z-index:2;width:235px;height:210px}.sceneNetwork span{position:absolute;width:40px;height:40px;border:2px solid #a67b47;border-radius:50%;background:#17110e}.sceneNetwork span:nth-child(1){left:98px;top:4px}.sceneNetwork span:nth-child(2){left:15px;top:80px}.sceneNetwork span:nth-child(3){right:15px;top:80px}.sceneNetwork span:nth-child(4){left:55px;bottom:10px}.sceneNetwork span:nth-child(5){right:55px;bottom:10px}.sceneNetwork:before,.sceneNetwork:after{content:"";position:absolute;left:38px;right:38px;top:101px;height:1px;background:#5f472f;transform:rotate(25deg);box-shadow:0 0 14px #a92e2880}.sceneNetwork:after{transform:rotate(-25deg)}.sceneFormula{position:relative;z-index:2;display:grid;grid-template-columns:1fr auto 1fr;gap:8px;align-items:center;width:250px}.sceneFormula span{border:1px solid #745539;padding:12px 8px;text-align:center;background:#16110e;color:#e0bd82;font-size:11px;font-weight:950;letter-spacing:.08em}.sceneFormula b{color:#7e2824}.prologueCopy{position:relative}.prologueIndex{font-size:10px;color:#967b5d;letter-spacing:.18em;font-weight:950}.prologueCopy h2{font-family:Impact,'Arial Narrow',Haettenschweiler,sans-serif;text-transform:uppercase;font-size:clamp(38px,6vw,72px);line-height:.9;letter-spacing:.02em;margin:11px 0 18px;color:#efe1cf}.prologueCopy p{font-family:Georgia,serif;color:#cbb9a5;font-size:clamp(17px,2vw,22px);line-height:1.55;margin:0;max-width:580px}.prologueCopy .accent{color:#d1a259}.prologueFooter{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;padding:16px 20px;border-top:1px solid #3d2e22;background:#080706}.prologueDots{display:flex;gap:7px;justify-content:center}.prologueDot{width:7px;height:7px;border-radius:50%;border:1px solid #6c5138;background:transparent}.prologueDot.active{background:#ae2c27;border-color:#d34b42;box-shadow:0 0 12px rgba(179,42,37,.5)}.prologueNav{display:flex;gap:8px}.prologueNav.right{justify-content:flex-end}.prologueBtn{border:1px solid #62482f;background:#16120f;color:#ead9c4;border-radius:4px;padding:10px 14px;font-weight:900;cursor:pointer}.prologueBtn.primary{background:linear-gradient(#a62b27,#701b18);border-color:#c64b42;color:white}.prologueBtn:disabled{opacity:.3;cursor:not-allowed}.prologueHint{font-size:9px;color:#6f6152;letter-spacing:.08em;text-align:center;margin-top:7px}.replayPrologue{border:1px solid #684e32;background:#17120e;color:#e7c98f;border-radius:6px;padding:8px 11px;font-size:12px;cursor:pointer}.prologueFlash{position:absolute;inset:0;background:#d5b787;opacity:0;pointer-events:none;z-index:10}.prologueShell.flash .prologueFlash{animation:flashFrame .32s ease-out}.prologueShell.blackout .prologueSceneWrap{animation:blackoutPulse .65s ease-out}@keyframes sceneIn{from{opacity:0;transform:translateY(9px);filter:blur(3px)}to{opacity:1;transform:none;filter:none}}@keyframes prologueBreath{from{transform:scale(1);filter:brightness(.9)}to{transform:scale(1.025);filter:brightness(1.08)}}@keyframes flashFrame{0%{opacity:0}20%{opacity:.13}100%{opacity:0}}@keyframes blackoutPulse{0%{opacity:1}46%{opacity:.1}68%{opacity:.1}100%{opacity:1}}\n@media(max-width:760px){.prologueFrame{min-height:calc(100vh - 18px);width:calc(100vw - 18px)}.prologueSceneWrap{padding:20px 18px}.prologueScene{grid-template-columns:1fr;gap:10px}.prologueVisual{height:210px}.prologueCopy{text-align:center}.prologueCopy p{margin:auto}.sceneSix{transform:scale(.78)}.prologueFooter{grid-template-columns:1fr 1fr}.prologueDots{grid-column:1/-1;grid-row:1}.prologueNav{grid-row:2}.prologueTop{padding:13px}.prologueSceneWrap{min-height:0}.prologueCopy h2{font-size:clamp(34px,12vw,54px)}}\n@media(max-width:460px){.prologueTopActions .prologueMiniBtn:first-child{display:none}.prologueBrand{font-size:8px}.prologueVisual{height:175px}.sceneGlyph{font-size:64px}.scenePaper{transform:scale(.72) rotate(-4deg)}.sceneQuotes{transform:scale(.82)}.sceneMissing{transform:scale(.72)}.sceneNetwork{transform:scale(.74)}.sceneFormula{transform:scale(.82)}.prologueCopy p{font-size:16px}.prologueFooter{padding:12px}.prologueBtn{padding:9px 10px;font-size:12px}}\n'''
if css_anchor not in s: raise SystemExit('CSS anchor missing')
s=s.replace(css_anchor,css+css_anchor,1)

body_anchor='<body><main class="wrap">'
prologue='''<body>\n<section id="prologue" class="prologueShell" aria-label="Prólogo de La Última Reunión">\n  <div class="prologueFlash"></div>\n  <div class="prologueFrame">\n    <div class="prologueTop"><div><div class="prologueBrand">EXPEDIENTES · CASO 001</div><div class="prologueHint">ARCHIVO AUDIOVISUAL · ACCESO PREVIO A LA INVESTIGACIÓN</div></div><div class="prologueTopActions"><button id="prologueSound" class="prologueMiniBtn" type="button">🔇 ACTIVAR AMBIENTE</button><button id="prologueSkip" class="prologueMiniBtn" type="button">SALTAR INTRO</button></div></div>\n    <div class="prologueSceneWrap"><div id="prologueScene" class="prologueScene"></div></div>\n    <div class="prologueFooter"><div class="prologueNav"><button id="prologuePrev" class="prologueBtn" type="button">← ANTERIOR</button></div><div><div id="prologueDots" class="prologueDots"></div><div id="prologueCounter" class="prologueHint">EXPEDIENTE 01 / 06</div></div><div class="prologueNav right"><button id="prologueNext" class="prologueBtn primary" type="button">CONTINUAR →</button></div></div>\n  </div>\n</section>\n<main class="wrap">'''
if body_anchor not in s: raise SystemExit('body anchor missing')
s=s.replace(body_anchor,prologue,1)

# add replay button beside kit printable
old='<span class="previewBadge">REV01 · PREVIEW</span><a class="tag" href="../caso001/printables/" target="_blank" rel="noopener">KIT IMPRIMIBLE</a>'
new='<span class="previewBadge">REV01 · PREVIEW</span><button id="replayPrologue" class="replayPrologue" type="button">VER PRÓLOGO</button><a class="tag" href="../caso001/printables/" target="_blank" rel="noopener">KIT IMPRIMIBLE</a>'
if old not in s: raise SystemExit('top actions anchor missing')
s=s.replace(old,new,1)

js_anchor="const theory=new Map();\n"
js='''const PROLOGUE_SCENES=[\n {title:'La reunión',text:'Seis personas fueron convocadas. Todas llegaron con una historia propia. Ninguna imaginaba que, al terminar la noche, cada palabra iba a ser revisada.',visual:'six'},\n {title:'Algo estaba por salir a la luz',text:'La reunión no era rutinaria. Había información, decisiones y asuntos pendientes capaces de cambiar el equilibrio entre quienes estaban presentes.',visual:'paper'},\n {title:'Versiones cruzadas',text:'Después, los recuerdos dejaron de coincidir. Horarios, movimientos y conversaciones comenzaron a formar relatos distintos sobre una misma noche.',visual:'quotes'},\n {title:'Algo falta',text:'Entre lo que se dijo, lo que quedó registrado y lo que apareció después, hay una ausencia. Algo importante no está donde debería estar.',visual:'missing'},\n {title:'La investigación',text:'No confíen en una sola pista. Crucen testimonios, tiempos, accesos, objetos y contradicciones. La verdad aparece cuando varias piezas encajan a la vez.',visual:'network'},\n {title:'El expediente se abre',text:'Para cerrar el caso deberán sostener una reconstrucción completa: persona, escena, objeto y motivo. Una acusación sin conexión no alcanza.',visual:'formula'}\n];\nlet prologueIndex=0,prologueAudio=null,prologueGain=null,prologueSoundOn=false;\nfunction prologueVisual(kind){\n if(kind==='six')return '<div class="sceneSix"><i></i><i></i><i></i><i></i><i></i><i></i></div>';\n if(kind==='paper')return '<div class="scenePaper"></div>';\n if(kind==='quotes')return '<div class="sceneQuotes"><span style="--r:-2deg">“Yo estaba en otro lugar.”</span><span style="--r:1deg">“Eso no fue así.”</span><span style="--r:-1deg">“Falta una parte.”</span></div>';\n if(kind==='missing')return '<div class="sceneMissing">?</div>';\n if(kind==='network')return '<div class="sceneNetwork"><span></span><span></span><span></span><span></span><span></span></div>';\n return '<div class="sceneFormula"><span>PERSONA</span><b>+</b><span>ESCENA</span><span>OBJETO</span><b>+</b><span>MOTIVO</span></div>';\n}\nfunction renderPrologueScene(direction=1){\n const scene=PROLOGUE_SCENES[prologueIndex],shell=$('#prologue'),box=$('#prologueScene');\n box.style.animation='none';void box.offsetWidth;box.style.animation='';\n box.innerHTML=`<div class="prologueVisual">${prologueVisual(scene.visual)}</div><div class="prologueCopy"><div class="prologueIndex">ARCHIVO ${String(prologueIndex+1).padStart(2,'0')} · 06</div><h2>${esc(scene.title)}</h2><p>${esc(scene.text)}</p></div>`;\n $('#prologueCounter').textContent=`EXPEDIENTE ${String(prologueIndex+1).padStart(2,'0')} / 06`;\n $('#prologueDots').innerHTML=PROLOGUE_SCENES.map((_,i)=>`<span class="prologueDot ${i===prologueIndex?'active':''}"></span>`).join('');\n $('#prologuePrev').disabled=prologueIndex===0;\n $('#prologueNext').textContent=prologueIndex===PROLOGUE_SCENES.length-1?'ABRIR EXPEDIENTE →':'CONTINUAR →';\n shell.classList.remove('flash','blackout');void shell.offsetWidth;shell.classList.add(prologueIndex===3?'blackout':'flash');\n}\nfunction closePrologue(){sessionStorage.setItem('pc_exp_rev01_prologue_seen','1');$('#prologue').classList.add('hidden');stopPrologueSound()}\nfunction openPrologue(force=false){prologueIndex=0;$('#prologue').classList.remove('hidden');renderPrologueScene();if(force)sessionStorage.removeItem('pc_exp_rev01_prologue_seen')}\nfunction nextPrologue(){if(prologueIndex>=PROLOGUE_SCENES.length-1){closePrologue();return}prologueIndex++;renderPrologueScene(1)}\nfunction prevPrologue(){if(prologueIndex<=0)return;prologueIndex--;renderPrologueScene(-1)}\nfunction stopPrologueSound(){if(prologueGain){try{prologueGain.gain.setTargetAtTime(0,prologueAudio.currentTime,.08)}catch{}}prologueSoundOn=false;const b=$('#prologueSound');if(b)b.textContent='🔇 ACTIVAR AMBIENTE'}\nasync function togglePrologueSound(){\n if(prologueSoundOn){stopPrologueSound();return}\n try{\n   const AC=window.AudioContext||window.webkitAudioContext;prologueAudio=prologueAudio||new AC();if(prologueAudio.state==='suspended')await prologueAudio.resume();\n   if(!prologueGain){\n     prologueGain=prologueAudio.createGain();prologueGain.gain.value=0;prologueGain.connect(prologueAudio.destination);\n     const o1=prologueAudio.createOscillator(),o2=prologueAudio.createOscillator(),lfo=prologueAudio.createOscillator(),lfoGain=prologueAudio.createGain();\n     o1.type='sine';o1.frequency.value=47;o2.type='triangle';o2.frequency.value=71;lfo.type='sine';lfo.frequency.value=.12;lfoGain.gain.value=.012;lfo.connect(lfoGain);lfoGain.connect(prologueGain.gain);o1.connect(prologueGain);o2.connect(prologueGain);o1.start();o2.start();lfo.start();\n   }\n   prologueGain.gain.setTargetAtTime(.018,prologueAudio.currentTime,.18);prologueSoundOn=true;$('#prologueSound').textContent='🔊 AMBIENTE ACTIVO';\n }catch(e){toast('El navegador no permitió activar el ambiente.',true)}\n}\n'''
if js_anchor not in s: raise SystemExit('js anchor missing')
s=s.replace(js_anchor,js_anchor+js,1)

# bind buttons before normal bindings
bind_anchor="$('#tabCreate').onclick=()=>setEntryMode('create');"
bind='''$('#prologueNext').onclick=nextPrologue;$('#prologuePrev').onclick=prevPrologue;$('#prologueSkip').onclick=closePrologue;$('#prologueSound').onclick=togglePrologueSound;$('#replayPrologue').onclick=()=>openPrologue(true);document.addEventListener('keydown',e=>{if($('#prologue').classList.contains('hidden'))return;if(e.key==='ArrowRight'||e.key==='Enter')nextPrologue();if(e.key==='ArrowLeft')prevPrologue();if(e.key==='Escape')closePrologue()});\n'''
if bind_anchor not in s: raise SystemExit('bind anchor missing')
s=s.replace(bind_anchor,bind+bind_anchor,1)

# after url params are known, decide whether prologue shows; invites skip automatically
url_anchor="buildCharacters();buildTheory();const urlParams=new URLSearchParams(location.search);const portalAccess=String(urlParams.get('access')||'').trim();const invitedRoom=urlParams.get('room');"
url_new=url_anchor+"if(invitedRoom||sessionStorage.getItem('pc_exp_rev01_prologue_seen')==='1'){$('#prologue').classList.add('hidden')}else{renderPrologueScene()}"
if url_anchor not in s: raise SystemExit('url anchor missing')
s=s.replace(url_anchor,url_new,1)

# bump adapter cache key only; same production adapter
s=s.replace("../caso001/p2-multiplayer-adapter.js?v=rev01-shell-1","../caso001/p2-multiplayer-adapter.js?v=rev01-prologue-2")

p.write_text(s)
print('P2.12D.2 prologue patched')
